			Errflag = 3

			/* find a state where "error" is a legal shift action */
			for pgp >= 0 {
				pgn = int(pgPact[pgS[pgp].yys]) + pgErrCode
				if pgn >= 0 && pgn < pgLast {
					pgstate = int(pgAct[pgn]) /* simulate a shift of "error" */
					if int(pgChk[pgstate]) == pgErrCode {
						goto pgstack
					}
				}

				/* the current p has no shift on "error", pop stack */
				if pgDebug >= 2 {
					__yyfmt__.Printf("error recovery pops state %d\n", pgS[pgp].yys)
				}
				pgp--
			}
